import { dateParts, resultFor, selectMatches } from './logic.js';
const configs=[['united','맨유','맨체스터 유나이티드','MANCHESTER UNITED','#a51d2d','#fff'],['spurs','토트넘','토트넘 홋스퍼','TOTTENHAM HOTSPUR','#152440','#fff'],['atleti','아틀레티코 마드리드','아틀레티코 마드리드','ATLÉTICO DE MADRID','#ba2635','#fff'],['real','레알 마드리드','레알 마드리드','REAL MADRID','#f6f3e9','#27261f'],['incheon','인천 유나이티드','인천 유나이티드','INCHEON UNITED','#1261a5','#fff']];
let data, selected='main', sub='schedule', busy=false;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const url=v=>{try{const u=new URL(v,location.href);return ['http:','https:'].includes(u.protocol)?esc(u.href):'#'}catch{return '#'}};
const img=(t,cls='')=>`<img class="${cls}" src="${url(t.logo)}" alt="${esc(t.name)} 엠블럼" width="44" height="44" loading="lazy">`;
const theme=c=>`--team:${c[4]};--team-ink:${c[5]}`;
const stamp=v=>{if(!v)return '수집 시각 없음';const d=dateParts(v);return `${d.month}.${d.day} ${d.time} KST`};
const teamData=k=>data?.teams.find(t=>t.key===k);
function side(t,away=false){return `<div class="side ${away?'away':''}">${img(t)}<span>${esc(t.name)}</span></div>`}
function match(m,t){const d=dateParts(m.kickoff||m.date);const done=m.status==='finished';const state=m.status==='live'?'진행 중':m.status==='postponed'?'경기 연기':m.status==='cancelled'?'경기 취소':null;const r=resultFor(m,t.id);const meta=`<div class="match-meta"><span class="upcoming-date">${d.valid?`${d.month}.${d.day} (${d.weekday})`:'날짜 확정 대기'}</span><span>·</span><span class="competition">${esc(m.competition)}</span><span class="venue-tag">${String(m.home.id)===String(t.id)?'홈':'원정'}${m.neutral?' · 중립':''}</span></div>`;const center=done||m.status==='live'?`<span class="score">${m.home.score}<small> : </small>${m.away.score}</span><span class="result-note">${done?`<span class="result ${r==='승'?'win':r==='무'?'draw':'loss'}">${r}</span><span>종료</span><span class="chevron">⌄</span>`:'진행 중'}</span>`:state?`<span class="tbd">${state}</span>`:m.timeStatus==='confirmed'&&d.valid?`<span class="kickoff">${d.time}</span><span class="kst">KST</span>`:`<span class="tbd">${m.timeStatus==='pending'?'일정 확정 대기':'시간 확인 중'}</span>`;const body=meta+`<div class="match-row">${side(m.home)}<div class="match-center">${center}</div>${side(m.away,true)}</div>`;
if(!done)return `<div class="fixture">${body}${m.timeConflict?'<p class="source-line">제공처 간 시간이 달라 최신 수집값을 표시합니다. 원문 확인이 필요합니다.</p>':''}</div>`;
const goals=m.goals||[];return `<details class="detail-match"><summary aria-label="${esc(m.home.name)} ${m.home.score} 대 ${m.away.score} ${esc(m.away.name)}, 득점 상세">${body}</summary><div class="goal-list">${goals.map(g=>`<div class="goal"><time>${esc(g.minute)}′</time><div>${esc(g.player)}${g.penalty?' <b>PK</b>':''}${g.ownGoal?' <b>자책골</b>':''}${g.assist?`<small>도움 · ${esc(g.assist)}</small>`:''}</div><span class="goal-side">${g.side==='home'?'홈':'원정'}</span></div>`).join('')}${m.goalsStatus==='complete'&&!goals.length?'<p class="empty">득점 없이 종료된 경기입니다.</p>':m.goalsStatus!=='complete'?'<p class="empty">득점 상세를 추가 확인 중입니다. 아래 경기 원문에서 확인할 수 있습니다.</p>':''}<p class="source-line">${esc(m.source)} · ${stamp(m.fetchedAt)} · <a href="${url(m.sourceUrl)}" target="_blank" rel="noopener noreferrer">경기 원문 ↗</a></p></div></details>`}
function list(t,type){const games=selectMatches(t.matches)[type];return `<section><div class="list-label"><b>${type==='upcoming'?'다가오는 경기':'최근 경기'}</b><span>${type==='upcoming'?'NEXT 3':'LAST 2'}</span></div>${games.length?games.map(m=>match(m,t)).join(''):'<p class="empty">공개된 경기 정보를 확인 중입니다.</p>'}${games.length<(type==='upcoming'?3:2)?'<p class="source-line">현재 공개 소스에서 확인 가능한 경기만 표시합니다.</p>':''}</section>`}
function refreshBar(title,en=''){return `<div class="section-line"><h2>${title}<span class="en">${en}</span></h2><div class="refresh-line"><span>데이터 수집 ${stamp(data.generatedAt)}</span><button class="refresh" data-refresh ${busy?'disabled':''}>↻ ${busy?'확인 중':'새로고침'}</button></div></div>`}
function freshness(){const age=Date.now()-Date.parse(data.generatedAt);return age>2*3600000?'<div class="status-banner">데이터 수집 후 2시간 이상 지났습니다. 마지막으로 확인된 정보를 표시 중이며 최신 일정은 경기 원문에서도 확인해 주세요.</div>':''}
function card(t,c){return `<article class="team-card" style="${theme(c)}"><a class="card-header" href="#${c[0]}/schedule">${img(t,'crest')}<div><h2>${c[2]}</h2><p>${c[3]}</p></div><span class="arrow">↗</span></a><div class="card-content">${list(t,'upcoming')}${list(t,'recent')}</div>${t.stale?'<div class="status-banner">일부 연결에 실패하여 이전 수집 데이터를 표시합니다.</div>':''}</article>`}
function render(){if(!data)return;document.querySelector('#team-nav').innerHTML=`<button class="nav-tab ${selected==='main'?'active':''}" data-team="main" aria-current="${selected==='main'?'page':'false'}"><span class="main-icon">⌂</span>메인</button>`+configs.map(c=>`<button class="nav-tab ${selected===c[0]?'active':''}" data-team="${c[0]}" aria-current="${selected===c[0]?'page':'false'}">${img(teamData(c[0]))}${c[1]}</button>`).join('');let html='';
if(selected==='main'){const count=data.teams.reduce((n,t)=>n+selectMatches(t.matches).upcoming.length,0);html=`<section class="hero"><div><div class="eyebrow">YOUR CLUBS. YOUR MATCHDAY.</div><h1>다섯 팀의 모든 순간,<br><span>하나의 매치데이.</span></h1><p>응원하는 팀의 다음 경기부터 마지막 골까지.<br>우리의 축구 시간은 언제나 한국시간.</p></div><div class="hero-numbers"><div><strong>05</strong><small>MY CLUBS</small></div><div><strong>${String(count).padStart(2,'0')}</strong><small>UPCOMING</small></div></div></section>${freshness()}${refreshBar('우리의 다음 경기','MATCH CENTER')}<p class="refresh-help">화면을 열 때 최신 저장 데이터를 조회합니다. 자동 수집은 약 30분 간격이며 지연될 수 있습니다. 최근 스코어를 누르면 득점 상세가 열립니다.</p><div class="grid">${configs.map(c=>card(teamData(c[0]),c)).join('')}</div>`}
else{const c=configs.find(c=>c[0]===selected),t=teamData(selected),s=t.standings;const rank=s?.rows.find(r=>String(r.id)===String(t.id))?.rank;html=`<section class="team-hero" style="${theme(c)}">${img(t,'crest')}<div><div class="eyebrow">${c[3]}</div><h1>${c[2]}</h1><p>${esc(s?.league||t.league)} · ${esc(s?.season||'')}</p></div>${rank?`<div class="hero-rank">${rank}<small>리그 순위</small></div>`:''}</section><nav class="subtabs" aria-label="팀 정보">${[['schedule','일정'],['table','순위'],['news','뉴스']].map(([k,n])=>`<button data-sub="${k}" class="${sub===k?'active':''}" aria-current="${sub===k?'page':'false'}">${n}</button>`).join('')}</nav>${freshness()}${refreshBar(sub==='schedule'?'매치데이':sub==='table'?(s?.league||'리그 순위'):'팀의 최신 소식')}`;
if(sub==='schedule')html+=`<div class="team-schedule"><div class="panel">${list(t,'upcoming')}</div><div class="panel">${list(t,'recent')}</div></div><p class="data-note">최근 경기 또는 스코어를 눌러 득점자와 득점시간을 확인하세요. PK·자책골·도움은 제공된 경우 표시합니다.<br>일정 수집: ${stamp(t.fetchedAt)} · ${esc(t.source)}${t.stale?' · 이전 데이터 사용 중':''}</p>`;
if(sub==='table')html+=s?.rows?.length?`<p class="refresh-help">${esc(s.season)} · 수집 ${stamp(s.fetchedAt)} · 모바일에서는 표를 좌우로 밀어 볼 수 있습니다.</p><div class="table-wrap" tabindex="0" role="region" aria-label="${esc(s.league)} 순위표"><table><thead><tr>${['순위','팀','경기','승','무','패','득실차','승점'].map(x=>`<th scope="col">${x}</th>`).join('')}</tr></thead><tbody>${s.rows.map(r=>`<tr class="${String(r.id)===String(t.id)?'highlight':''}"><td>${r.rank}</td><td><div>${img(r)}<span>${esc(r.name)}</span></div></td><td>${r.played}</td><td>${r.wins}</td><td>${r.draws}</td><td>${r.losses}</td><td>${r.gd>0?'+':''}${r.gd}</td><td>${r.points}</td></tr>`).join('')}</tbody></table></div><p class="source-line">${esc(s.source)} · <a href="${url(s.sourceUrl)}" target="_blank" rel="noopener noreferrer">순위 원문 ↗</a>${s.stale?' · 이전 수집 데이터':''}</p>`:'<p class="empty">현재 리그 순위를 확인 중입니다.</p>';
if(sub==='news')html+=`<p class="refresh-help">수집 ${stamp(t.newsFetchedAt)} · 뉴스 원문은 새 창에서 열립니다.</p><div class="news-grid">${(t.news||[]).map(n=>`<a class="news-card" href="${url(n.url)}" target="_blank" rel="noopener noreferrer"><div><div class="news-source"><span>${esc(n.source)}</span><time>${stamp(n.publishedAt)}</time></div><h3>${esc(n.title)}</h3></div><span class="read-link">원문 읽기 ↗</span></a>`).join('')||'<p class="empty">최신 뉴스를 확인 중입니다.</p>'}</div>`;
}document.querySelector('#app').innerHTML=html;document.title=`Jarvis Football${selected==='main'?' — 우리의 다음 경기':' · '+configs.find(c=>c[0]===selected)[2]}`;}
function route(){const [key,view]=location.hash.slice(1).split('/');selected=configs.some(c=>c[0]===key)?key:'main';sub=['schedule','table','news'].includes(view)?view:'schedule';render()}
function notify(msg){const n=document.querySelector('#notice');n.textContent=msg;n.classList.add('visible');setTimeout(()=>n.classList.remove('visible'),4000)}
async function refresh(manual=false){if(busy)return;busy=true;if(data)render();try{const r=await fetch(`./data/football.json?v=${Date.now()}`,{cache:'no-store',signal:AbortSignal.timeout(15000)});if(!r.ok)throw Error(r.status);const next=await r.json();if(next.schemaVersion!==1||next.teams?.length!==5)throw Error('invalid data');data=next;route();if(manual)notify('최신 저장 데이터를 확인했습니다. 수집 시각을 확인해 주세요.')}catch{if(data)notify('연결이 원활하지 않아 현재 표시된 데이터를 유지합니다.');else document.querySelector('#app').innerHTML='<div class="loading"><p>경기 데이터를 불러오지 못했습니다.</p><button class="refresh" data-refresh>다시 시도</button></div>'}finally{busy=false;if(data)render()}}
document.addEventListener('click',e=>{const t=e.target.closest('[data-team]'),s=e.target.closest('[data-sub]');if(t)location.hash=t.dataset.team==='main'?'main':t.dataset.team+'/schedule';if(s)location.hash=selected+'/'+s.dataset.sub;if(e.target.closest('[data-refresh]'))refresh(true)});
window.addEventListener('hashchange',route);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')refresh()});refresh();
